const lines=[],groups={};let active=null;const log=(...a)=>lines.push(a.join(' '));
function test(label,callback){if(CASE&&CASE!==label)return;const start=lines.length;try{callback()}catch(e){log(label,'ERROR',e.name,e.message)}finally{if(active)active.remove();active=null}groups[label]=lines.slice(start)}
function input(attrs={}){const i=document.createElement('input');for(const [k,v]of Object.entries(attrs))i.setAttribute(k,v);i.type='color';return i}
function view(value){if(!value.startsWith('color('))return value;const m=value.match(/^color\(([^ ]+) ([^)]+)\)$/);return [m[1],...m[2].replace('/',' ').trim().split(/\s+/).map(v=>+Number(v).toFixed(3))]}
function sample(label,values,attrs={}){const i=input(attrs);for(const v of values){i.value=v;log(label,JSON.stringify([v,view(i.value)]))}}
function mount(html){active=document.createElement('div');active.innerHTML=html;document.body.append(active);return active}
test('color-basic',()=>sample('color-basic',['','bad','#000000','#ABCDEF','#abc','#abcd','#12345678','red','rebeccapurple','transparent','rgb(255, 0, 0)','hsl(120 100% 50%)','hwb(120 0% 0%)','lab(50% 0 0)','lch(50 20 30)','oklab(.7 .2 .1)','oklch(.7 .2 30)','color(display-p3 1 0 0)','color(srgb-linear .5 .5 .5)','color(xyz-d50 .2 .3 .4)','color(a98-rgb .2 .3 .4)','color(prophoto-rgb .2 .3 .4)','color(rec2020 .2 .3 .4)','currentcolor']));
test('color-syntax',()=>sample('color-syntax',[' RED ','red\n','\u00a0red\u00a0','/**/red/**/','r\\65 d','rgb(1/**/ 2 3)','rgb(1 2 3 / .5)','rgb(1, 2, 3, .5)','rgba(1 2 3)','rgb(1, 2%, 3)','rgb(1% 2 3%)','rgb(1 2,3)','rgb(1,2,3 / .5)','hsl(120 1 .5)','hsl(120, 100%, 50%)','hsl(.5turn 100% 50%)','hsl(200grad 100% 50%)','hsl(3.141592653589793rad 100% 50%)','#12','#12345','123456','#123456x','red blue','red;','var(--x)','color-mix(in srgb,red,blue)']));
test('color-calc',()=>sample('color-calc',['rgb(calc(100 + 155) 0 0)','rgb(1 2 3 / calc(.5))','rgb(calc(100% / 2) 0% 0%)','hsl(calc(.25turn + 90deg) 100% 50%)','rgb(min(10, 20) 0 0)','rgb(max(10, 20) 0 0)','rgb(clamp(0, 200, 100) 0 0)','rgb(calc(2 * (30 + 10)) 0 0)','rgb(calc(10-2) 0 0)','rgb(calc(1px) 0 0)','rgb(calc(1 + 20%) 0 0)','rgb(calc(1 / 0) 0 0)','rgb(calc(0 / 0) 0 0)','rgb(calc(1e999) 0 0)']));
test('color-rounding',()=>sample('color-rounding',['rgb(.49 .5 1.5)','rgb(1.49 1.5 2.5)','rgb(-10 300 1e999)','rgb(none none none)','rgba(255,0,0,-1)','rgba(255,0,0,2)','hsl(1e999 100% 50%)','color(srgb 1e999 0 0)','color(display-p3 1.84 -.19 .72 / .6)']));
test('color-alpha',()=>sample('color-alpha',['#12345678','rgba(255,0,0,.5)','transparent','#abcd','red','color(srgb .1 .2 .3 / .1)'],{alpha:''}));
test('color-p3',()=>sample('color-p3',['#12345678','rgba(255,0,0,.5)','color(display-p3 1 0 0)','color(display-p3 1.84 -.19 .72 / .6)'],{colorspace:'display-p3'}));
test('color-p3-alpha',()=>sample('color-p3-alpha',['#12345678','rgba(255,0,0,.5)','color(display-p3 1 0 0)','color(display-p3 1.84 -.19 .72 / .6)'],{alpha:'',colorspace:'display-p3'}));
test('color-dynamic',()=>{const i=input({value:'#12345678'});for(const dirty of [false,true]){if(dirty)i.value='#12345678';for(const [k,v]of [['alpha',''],['colorspace','display-p3'],['colorspace','limited-srgb'],['alpha',null],['alpha','']]){if(v===null)i.removeAttribute(k);else i.setAttribute(k,v);log('color-dynamic',JSON.stringify([dirty,k,v,view(i.value),i.defaultValue]))}}});
test('color-reflection',()=>{const i=input();log('color-reflection','initial',i.alpha,i.colorSpace);i.alpha=true;i.colorSpace='DISPLAY-P3';i.value='red';log('color-reflection',JSON.stringify([i.alpha,i.colorSpace,i.getAttribute('alpha'),i.getAttribute('colorspace'),view(i.value)]));i.colorSpace='unknown';i.alpha=false;log('color-reflection',JSON.stringify([i.alpha,i.colorSpace,i.getAttribute('alpha'),i.getAttribute('colorspace'),view(i.value)]));});
test('color-parser-order',()=>{for(const markup of ['<input type=color value=#ABC>','<input value=#ABC type=color>','<input type=color value=#12345678 alpha>','<input alpha type=color value=#12345678>','<input type=color colorspace=display-p3 value=red>','<input value=red colorspace=display-p3 type=color>']){const b=mount(markup);log('color-parser-order',markup,JSON.stringify(view(b.firstChild.value)));b.remove();active=null}});
test('color-copies-reset',()=>{const b=mount('<form><input name=c type=color value=red><input name=a type=color value=#12345678 alpha></form>'),f=b.firstChild;for(const i of f.querySelectorAll('input')){i.value='#abcdef';i.defaultValue='#123';const c=i.cloneNode();log('color-copies-reset','copy',i.name,JSON.stringify([view(i.value),view(c.value),c.defaultValue]));}log('color-copies-reset','data',JSON.stringify([...new FormData(f)].map(([k,v])=>[k,view(v)])));f.reset();log('color-copies-reset','reset',JSON.stringify([...new FormData(f)].map(([k,v])=>[k,view(v)])))});
test('color-type-changes',()=>{for(const dirty of [false,true])for(const next of ['color','text','hidden']){const i=document.createElement('input');i.defaultValue='#ABC';if(dirty)i.value='red';i.type='color';i.type=next;log('color-type-changes',JSON.stringify([dirty,next,i.value,i.defaultValue]))}});
test('color-intrinsics',()=>{const i=input();const ex=RegExp.prototype.exec,n=Number,p=Math.pow;let calls=0;const poison=()=>{calls++;throw Error('author replacement')};try{RegExp.prototype.exec=poison;globalThis.Number=poison;Math.pow=poison;i.value='oklch(.7 .2 30)';log('color-intrinsics',i.value,calls)}finally{RegExp.prototype.exec=ex;globalThis.Number=n;Math.pow=p}});
