test('color-math-grammar',()=>sample('color-math-grammar',['rgb(calc(1/**/+/**/2) 0 0)','rgb(calc(1/**/ + /**/2) 0 0)','rgb(calc(10 + -2) 0 0)','rgb(calc(10 - -2) 0 0)','rgb(calc(10 +2) 0 0)','rgb(calc(2*3 + 4/2) 0 0)','rgb(calc((1 + 2)*3) 0 0)','rgb(calc(10% / 2%) 0 0)','rgb(abs(-3) 0 0)','rgb(sign(-3) 0 0)','rgb(min(NaN,10) 0 0)','rgb(clamp(10,5,0) 0 0)','hwb(120 0 0)','hsl(120,100,50)','rgba(1,2,3,none)','rgb(1 2 3 / none)','color(display-p3 1 0 0 / none)']));
